def main():
    load_env()
    token = get_token()
    results = []
    for course_id, description in DESCRIPTIONS.items():
        if "—" in description:
            raise ValueError(f"{course_id}: em dash found")
        course = api_get(f"courses/{course_id}", token)["courses"][0]
        before = course.get("description") or ""
        course["description"] = description
        status, resp = api_put(f"courses/{course_id}", token, {"course": course})
        if status != 200:
            raise RuntimeError(f"{course_id}: {status} {resp}")
        results.append({
            "id": course_id,
            "title": course.get("title"),
            "before_len": len(before),
            "after_len": len(description),
        })
        print(f"{course_id}: description {len(before)} -> {len(description)}")
    out = os.path.join(os.path.dirname(__file__), "_description_normalization_2026_08_25.json")
    with open(out, "w", encoding="utf-8") as f:
        json.dump(results, f, ensure_ascii=False, indent=2)
    print(f"saved {out}")


if __name__ == "__main__":
    main()
